stack_wait:
if (recipe.time)
	var/buildtime = recipe.time
	if (H && H.getStatCoeff("strength"))
		buildtime /= H.getStatCoeff("strength")
		buildtime /= (H.getStatCoeff("crafting") * H.getStatCoeff("crafting"))

	buildtime = round(buildtime)

	to_chat(user, "<span class='notice'>Building [recipe.title] ...</span>")
	if (!do_after(user, buildtime) || !crafting_recipe_allowed(H, "[recipe.result_type]"))
		if (H.key in handReturnMap)
			var/atom/O
			var/datum/A
			for(A in handReturnMap[H.key])
				O = new A.type()
				H.put_in_hands(O)
			handReturnMap.Remove(H.key)
		return

stack_refund:
else if (istype(O, /obj/structure/research_bench))
	// The bench belongs to the faction that built it (Phase 4.1).
	// Re-check the cap HERE, not just pre-build: the earlier check
	// passed ~25s ago and several members can build in parallel
	// (time-of-check/time-of-use), so validate again now that the
	// bench exists but hasn't been assigned to the faction yet --
	// count_faction_benches() only counts assigned benches, so the
	// count is still accurate at this point.
	var/obj/structure/research_bench/RBN = O
	if (H.civilization && H.civilization != "none")
		if (map && map.count_faction_benches(H.civilization) >= map.get_bench_cap(H.civilization))
			to_chat(H, SPAN_WARNING("Your faction hit its research bench cap while this one was being built - it falls apart, and you recover the materials."))
			// Refund: the materials were already consumed by use() above.
			if (required > 0)
				new type(get_turf(H), required)
			qdel(O)
			return
		RBN.faction = H.civilization

windowclose:
/client/verb/windowclose(var/atomref as text)
	set hidden = TRUE						// hide this verb from the user's panel
	set name = ".windowclose"			// no autocomplete on cmd line

	//to_chat(world, "windowclose: [atomref]")
	if (atomref!="null")				// if passed a real atomref
		var/hsrc = locate(atomref)	// find the reffed atom
		if (hsrc)
			//to_chat(world, "[src] Topic [href] [hsrc]")
			usr = mob
			Topic("close=1", list("close"="1"), hsrc)	// this will direct to the atom's
			return										// Topic() proc via client.Topic()

	// no atomref specified (or not found)
	// so just reset the user mob's machine var
	if (src && mob)
		//to_chat(world, "[src] was [mob.machine], setting to null")
		mob.unset_using_object()
	return

legacy_wait:
/mob/var/may_do_after = TRUE
#ifdef CIV13_GAMEPLAY_BRIDGE
#define CIV13_GAMEPLAY_WAIT_GUARDS
#endif
#ifdef CIV13_GAMEPLAY_BRIDGE
/proc/do_after(mob/user, delay, atom/target = null, needhand = TRUE, progress = TRUE, var/incapacitation_flags = INCAPACITATION_DEFAULT, can_move = FALSE, check_for_repeats = TRUE, datum/pickaxe_mining_action/mining_context = null, datum/gameplay_action_lease/gameplay_context = null)
#else
/proc/do_after(mob/user, delay, atom/target = null, needhand = TRUE, progress = TRUE, var/incapacitation_flags = INCAPACITATION_DEFAULT, can_move = FALSE, check_for_repeats = TRUE, datum/pickaxe_mining_action/mining_context = null)
#endif
	if (!user || !user.may_do_after)
		return FALSE
#ifdef CIV13_GAMEPLAY_BRIDGE
	if (!isnull(gameplay_context) && !isnull(mining_context))
		return FALSE
	var/datum/gameplay_action_lease/gameplay_lease
	if (!isnull(gameplay_context))
		if (!istype(gameplay_context, /datum/gameplay_action_lease))
			return FALSE
		gameplay_lease = gameplay_context
		if (!gameplay_lease.claim_gather_wait(user, target))
			return FALSE
#endif
	if (!isnull(mining_context) && (!istype(mining_context, /datum/pickaxe_mining_action) || !mining_context.claim(user, target)))
		return FALSE
	if (mining_context)
		mining_context.wait_started = TRUE
	user.survival_action_started()

	if (check_for_repeats)
		user.may_do_after = FALSE

	var/target_loc = null

	if (target)
		target_loc = target.loc

	var/atom/original_loc = user.loc

	var/holding = user.get_active_hand()

	var/datum/progressbar/progbar
	if (progress)
		progbar = new(user, delay, target)
		if (mining_context)
			mining_context.progressbar = progbar

	var/endtime = world.time + delay
	var/starttime = world.time
	. = TRUE
	while (world.time < endtime)
		sleep(0.1)
#ifdef CIV13_GAMEPLAY_BRIDGE
		if (gameplay_lease && !gameplay_lease.valid())
			. = FALSE
			break
#endif
		if (mining_context && !mining_context.valid(user, target))
			. = FALSE
			break
		if (progress)
			progbar.update(world.time - starttime)

		if (!user || user.incapacitated(incapacitation_flags))
			. = FALSE
			break

		if (target_loc && (!target || target_loc != target.loc))
			. = FALSE
			break

		if (!can_move)
			if (user.loc != original_loc)
				. = FALSE
				break

		if (needhand)
			if (user.get_active_hand() != holding)
				. = FALSE
				break
	if (mining_context && !mining_context.valid(user, target))
		. = FALSE
	if (user)
		user.may_do_after = TRUE
		if (mining_context)
			mining_context.wait_started = FALSE
		user.survival_action_finished()

	if (progbar)
		qdel(progbar)
#ifdef CIV13_GAMEPLAY_BRIDGE
	if (gameplay_lease && !gameplay_lease.valid())
		. = FALSE
#endif
	if (mining_context)
		mining_context.progressbar = null

stack_admission:
if (!can_use(required))
	if (produced>1)
		to_chat(user, "<span class='warning'>You haven't got enough [src] to build \the [produced] [recipe.title]\s!</span>")
	else
		to_chat(user, "<span class='warning'>You haven't got enough [src] to build \the [recipe.title]!</span>")
	return

